import os
import re
from datetime import date
from PIL import Image, ImageOps, ImageFilter
import pytesseract
from openpyxl import Workbook

IMG_DIR = "/app/workspace/dataset/img"
OUT_XLSX = "/app/workspace/stat_ocr.xlsx"

# Priority-ordered keywords
KEYWORDS_PRIORITY = [
    ["GRAND TOTAL"],
    ["TOTAL RM", "TOTAL: RM"],
    ["TOTAL AMOUNT"],
    ["TOTAL DUE", "AMOUNT DUE", "BALANCE DUE", "NETT TOTAL", "NET TOTAL", "TOTAL", "AMOUNT"],
]

EXCLUDE_KEYWORDS = [
    "SUBTOTAL", "SUB TOTAL", "TAX", "GST", "SST", "DISCOUNT", "CHANGE", "CASH TENDERED"
]

AMOUNT_RE = re.compile(r"(?<!\d)(?:\d{1,3}(?:,\d{3})*|\d+)(?:\.\d{2})?")
DATE_YMD_RE = re.compile(r"\b(\d{4})[-/.](\d{1,2})[-/.](\d{1,2})\b")
DATE_DMY_RE = re.compile(r"\b(\d{1,2})[-/.](\d{1,2})[-/.](\d{2,4})\b")
DATE_TEXT_RE = re.compile(r"\b(\d{1,2})\s*([A-Z]{3,9})\s*(\d{2,4})\b")
DATE_TEXT_RE2 = re.compile(r"\b([A-Z]{3,9})\s*(\d{1,2})\s*,?\s*(\d{2,4})\b")

MONTHS = {
    "JAN": 1, "JANUARY": 1,
    "FEB": 2, "FEBRUARY": 2,
    "MAR": 3, "MARCH": 3,
    "APR": 4, "APRIL": 4,
    "MAY": 5,
    "JUN": 6, "JUNE": 6,
    "JUL": 7, "JULY": 7,
    "AUG": 8, "AUGUST": 8,
    "SEP": 9, "SEPT": 9, "SEPTEMBER": 9,
    "OCT": 10, "OCTOBER": 10,
    "NOV": 11, "NOVEMBER": 11,
    "DEC": 12, "DECEMBER": 12,
}


def normalize_year(y: int) -> int:
    if y < 100:
        return 2000 + y if y <= 79 else 1900 + y
    return y


def try_make_date(y, m, d):
    try:
        return date(y, m, d)
    except Exception:
        return None


def parse_date(text: str):
    t = text.upper()
    # 1) YYYY-MM-DD like
    for m in DATE_YMD_RE.finditer(t):
        y, mo, d = map(int, m.groups())
        dt = try_make_date(y, mo, d)
        if dt:
            return dt.isoformat()
    # 2) DD/MM/YYYY or MM/DD/YYYY
    for m in DATE_DMY_RE.finditer(t):
        a, b, y = m.groups()
        a = int(a)
        b = int(b)
        y = normalize_year(int(y))
        # Prefer DD/MM if ambiguous
        dt = None
        if a > 12 and b <= 12:
            dt = try_make_date(y, b, a)
        elif b > 12 and a <= 12:
            dt = try_make_date(y, a, b)
        else:
            # ambiguous: treat as DD/MM
            dt = try_make_date(y, b, a)
            if not dt:
                dt = try_make_date(y, a, b)
        if dt:
            return dt.isoformat()
    # 3) Text months: 12 JAN 2023 / JAN 12 2023
    for m in DATE_TEXT_RE.finditer(t):
        d_s, mon_s, y_s = m.groups()
        mon = MONTHS.get(mon_s[:3], MONTHS.get(mon_s, None))
        if not mon:
            continue
        d = int(d_s)
        y = normalize_year(int(y_s))
        dt = try_make_date(y, mon, d)
        if dt:
            return dt.isoformat()
    for m in DATE_TEXT_RE2.finditer(t):
        mon_s, d_s, y_s = m.groups()
        mon = MONTHS.get(mon_s[:3], MONTHS.get(mon_s, None))
        if not mon:
            continue
        d = int(d_s)
        y = normalize_year(int(y_s))
        dt = try_make_date(y, mon, d)
        if dt:
            return dt.isoformat()
    return None


def clean_amount(num_str: str):
    if num_str is None:
        return None
    s = num_str.replace(",", "")
    try:
        if "." in s:
            val = float(s)
        else:
            val = float(s)
        return f"{val:.2f}"
    except Exception:
        return None


def extract_amount_from_lines(lines):
    # lines should be normalized uppercase (but keep original numeric chars)
    for kw_group in KEYWORDS_PRIORITY:
        for i, line in enumerate(lines):
            if any(ex in line for ex in EXCLUDE_KEYWORDS):
                continue
            if any(kw in line for kw in kw_group):
                nums = AMOUNT_RE.findall(line)
                if nums:
                    return clean_amount(nums[-1])
                # fallback to next line
                if i + 1 < len(lines):
                    nums2 = AMOUNT_RE.findall(lines[i + 1])
                    if nums2:
                        return clean_amount(nums2[-1])
    return None


def ocr_text_variants(path):
    img = Image.open(path)
    variants = []

    # Original
    variants.append(img)

    # Grayscale + autocontrast
    g = ImageOps.grayscale(img)
    g = ImageOps.autocontrast(g)
    variants.append(g)

    # Binarized
    b = g.point(lambda x: 0 if x < 160 else 255, mode='1')
    variants.append(b)

    # Slight blur to reduce noise then threshold
    g2 = g.filter(ImageFilter.MedianFilter(size=3))
    b2 = g2.point(lambda x: 0 if x < 170 else 255, mode='1')
    variants.append(b2)

    texts = []
    for v in variants:
        try:
            txt = pytesseract.image_to_string(v, lang='eng', config='--oem 1 --psm 6')
        except Exception:
            txt = pytesseract.image_to_string(v)
        texts.append(txt)
    return texts


def extract_fields(path):
    texts = ocr_text_variants(path)

    date_val = None
    total_val = None

    for txt in texts:
        if date_val is None:
            date_val = parse_date(txt)
        if total_val is None:
            lines = [ln.strip().upper() for ln in txt.splitlines() if ln.strip()]
            total_val = extract_amount_from_lines(lines)
        if date_val is not None and total_val is not None:
            break

    return date_val, total_val


filenames = sorted([f for f in os.listdir(IMG_DIR) if os.path.isfile(os.path.join(IMG_DIR, f))])
rows = []
for fname in filenames:
    path = os.path.join(IMG_DIR, fname)
    d, amt = extract_fields(path)
    rows.append([fname, d if d is not None else None, amt if amt is not None else None])

wb = Workbook()
ws = wb.active
ws.title = "results"
ws.append(["filename", "date", "total_amount"])
for row in rows:
    ws.append(row)

# Ensure only one sheet
for s in wb.sheetnames[1:]:
    del wb[s]

wb.save(OUT_XLSX)

print(f"Wrote {OUT_XLSX} with {len(rows)} rows")
